import{d as p,C as t,o as g,c as d,a3 as s,E as e,j as a,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第三十三章","description":"《正易心法》第三十三章——凡物之数，有进有退：盛衰之数相半，进以此数退以此数；一岁十二月、昼夜十二时、人寿百岁、干支相邻，皆见进退，细推物理无不如然。","frontmatter":{"title":"正易心法·第三十三章","description":"《正易心法》第三十三章——凡物之数，有进有退：盛衰之数相半，进以此数退以此数；一岁十二月、昼夜十二时、人寿百岁、干支相邻，皆见进退，细推物理无不如然。","category":"guide","aliases":["正易心法第三十三章","进以此数退以此数","进退相半"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-33.md","filePath":"yijing/zheng-yi-xin-fa/chapter-33.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-33.md"},x=p({...c,setup(u){const i=[{id:"z33-01",label:"一、有进有退",showLabel:!0,sentences:[["凡物之数，有进有退。进以此数，退以此数。"]],note:["万物的数理有进有退：进用这个数，退也用这个数。（**「这个数」是同一个数**——不是两套规律，是同一套规律的两个方向。**就像上山与下山：走的是同一条路，只是方向相反。**）"]},{id:"z33-02",label:"二、盛衰之数相半",showLabel:!0,sentences:[["大抵",{text:"物理",glossary:"wuli"},"，其",{text:"盛衰之数相半",glossary:"shengshuaiXiangban"},"。方其盛也，既以此数。及其衰也，亦以此数。"]],note:["大体上，事物的道理，盛的数量与衰的数量各占一半。正当它旺盛的时候，用的就是这个数；等到它衰退的时候，也用的是这个数。（**这不是经验归纳，而是循环本身的逻辑要求**：如果盛＞衰，事物会无限增长；如果盛＜衰，会最终归零——**只有盛＝衰，循环才能成立。** 所以「相半」是一条守恒律。）"]},{id:"z33-03",label:"三、一岁与昼夜",showLabel:!0,sentences:[["若一岁十二月，春夏为进数，秋冬为退数。昼夜十二时，自子为进数，自午为退数。"]],note:["比如一年十二个月：春夏是进数，秋冬是退数。昼夜十二时辰：从子时开始是进数，从午时开始是退数。（**两处都是「各占一半」**：一年前半年进、后半年退；一日前半日子→午进，后半日午→子退。**而子与午正是阴阳的两个极点**——子时一阳生，午时一阴生。）"]},{id:"z33-04",label:"四、人寿与干支",showLabel:!0,sentences:[["人寿百岁，前五十为进数，后五十为退数。以至甲为进数，乙为退数。子为进数，丑为退数。"]],note:["人的寿命百岁：前五十年是进数，后五十年是退数。乃至甲是进数、乙是退数；子是进数、丑是退数。（**用「进退相半」看人的一生**：前五十不是「好」，后五十不是「坏」——**进退是同一个数的两面。** 而天干地支的「甲进乙退、子进丑退」是最小单位的进退节律：**阴阳交替，一步一步。**）"]},{id:"z33-05",label:"五、细推物理",showLabel:!0,sentences:[["细推物理，无不如然。"]],note:["仔细推演万物之理，无不如此。（**这是《正易心法》中最强的一句普遍性宣称**——前面各章的「此象之自然」「自然吻合，无余欠矣」「无余蕴矣」都是针对具体命题的宣称，**而这一句是「万物之理，无一例外」。**）"]},{id:"z33-06",label:"六、世儒衍为一律",showLabel:!0,sentences:[["世儒论教，但",{text:"衍为一律",glossary:"yanyuYilv"},"，殊不明阴阳进退之理，惟真人独得其说。"]],note:["世间儒者论述教化，只是把一切展开成同一个标准，竟然不明白阴阳进退的道理——只有真人独自得到了这个说法。（**「衍为一律」的批评有三种可能的指向**：① 只用阳数（进数）推演，忽略阴数（退数）；② 用固定公式套用一切，不知同一个数在不同阶段意义不同；③ 把道德教化也一律化，**只讲进（努力、上进、成就），不讲退（收敛、谦退、知止）。** **三种合读，「一律」的本质是：只看到规律的一个方向。**）"]}],o=[{id:"wuli",term:"物理",pinyin:"wù lǐ",meaning:"事物的道理，万物运行的内在规律。非现代「物理学」。"},{id:"shengshuaiXiangban",term:"盛衰之数相半",pinyin:"shèng shuāi zhī shù xiāng bàn",meaning:"盛的数量与衰的数量各占一半。不是观察所得，而是循环本身的逻辑要求（守恒律）。"},{id:"yanyuYilv",term:"衍为一律",pinyin:"yǎn wéi yī lǜ",meaning:"推演成一个统一模式。衍是推演，一律是一个模式。麻衣批评：只知单向，不知进退。"}];return(b,n)=>{const r=t("DaoTextReading"),l=t("DaoKeywordCards");return g(),d("div",null,[n[0]||(n[0]=s("",20)),e(r,{colophon:"有进有退 · 盛衰相半 · 一岁昼夜人寿 · 无不如然",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第三十三章原文",sections:i,glossary:o}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入，用字随底本（「大抵物理」之「物理」指事物之理，非今日之学科），不作统一。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(l,{items:[{term:"进以此数退以此数",pinyin:["jìn","cǐ"],meaning:"进和退用的是同一个数——不是两套规律，是同一套规律的两个方向，如上山与下山同一条路。"},{term:"盛衰之数相半",pinyin:["shèng","shuāi"],meaning:"盛的数量与衰的数量各半。这是循环成立的逻辑要求，不是观察所得。"},{term:"一岁与昼夜",pinyin:["yī","suì"],meaning:"春夏为进、秋冬为退；子→午为进、午→子为退。子与午正是阴阳的两个极点。"},{term:"人寿百岁",pinyin:["rén","shòu"],meaning:"前五十为进、后五十为退——进退是同一个数，生死是同一件事的两面。"},{term:"衍为一律",pinyin:["yǎn","wéi"],meaning:"推演成一个统一模式。麻衣批评世儒只知单向，不明白阴阳进退之理。"}]}),n[3]||(n[3]=s("",25))])}}});export{y as __pageData,x as default};
